    public String parseOrderStatus(String status)
    {
        Map<String, Object> statuses = new HashMap<String, Object>() {{
            put( "Untouched", "open" );
            put( "Partial", "open" );
            put( "Canceled", "canceled" );
            put( "Closed", "closed" );
        }};
        return this.safeString(statuses, status, status);
    }

    public Object parseOrder(Object order, Map<String, Object> market)
    {
        //
        // fetchOrders / fetchOpenOrders
        //     {
        //       "id": 2605984008,
        //       "price": "55000",
        //       "amount": "0.00050000",
        //       "quantity": "0.00050000",
        //       "stopPrice": "0",
        //       "pairSymbol": "BTCUSDT",
        //       "pairSymbolNormalized": "BTC_USDT",
        //       "type": "buy",
        //       "method": "limit",
        //       "orderClientId": "f479bdb6-0965-4f03-95b5-daeb7aa5a3a5",
        //       "time": 0,
        //       "updateTime": 1618913083543,
        //       "status": "Untouched",
        //       "leftAmount": "0.00050000"
        //     }
        //
        // createOrder
        //     {
        //       "id": "2606935102",
        //       "quantity": "0.0002",
        //       "price": "56000",
        //       "stopPrice": null,
        //       "newOrderClientId": "98e5c491-7ed9-462b-9666-93553180fb28",
        //       "type": "buy",
        //       "method": "limit",
        //       "pairSymbol": "BTCUSDT",
        //       "pairSymbolNormalized": "BTC_USDT",
        //       "datetime": "1618916479523"
        //     }
        //
        String id = this.safeString(order, "id");
        String price = this.safeString(order, "price");
        String amountString = this.safeString2(order, "amount", "quantity");
        String amount = Precise.stringAbs(amountString);
        String remaining = this.safeString(order, "leftAmount");
        String marketId = this.safeString(order, "pairSymbol");
        String symbol = this.safeSymbol(marketId, market, (String) null, (String) null);
        String side = this.safeString(order, "type");
        String type = this.safeString(order, "method");
        String clientOrderId = this.safeString(order, "orderClientId");
        Long timestamp = (Long) this.safeInteger2(order, "updateTime", "datetime");
        String rawStatus = this.safeString(order, "status");
        String status = this.parseOrderStatus(rawStatus);
        return this.safeOrder(new HashMap<String, Object>() {{
            put( "info", order );
            put( "id", id );
            put( "price", price );
            put( "amount", amount );
            put( "remaining", remaining );
            put( "filled", null );
            put( "cost", null );
            put( "average", null );
            put( "status", status );
            put( "side", side );
            put( "type", type );
            put( "clientOrderId", clientOrderId );
            put( "timestamp", timestamp );
            put( "datetime", Btcturk.this.iso8601(timestamp) );
            put( "symbol", symbol );
            put( "fee", null );
        }}, market);
    }

